import React, { useState, useEffect } from "react";
import {
  FaUserEdit,
  FaLock,
  FaUser,
  FaEnvelope,
  FaTransgender,
  FaBirthdayCake,
  FaTimes,
} from "react-icons/fa";
import axiosClient from "../../utils/axiosConfig";

const PersonalInfo = () => {
  const [userInfo, setUserInfo] = useState({
    fullName: "",
    email: "",
    gender: "",
    birthDay: "",
    birthMonth: "",
    birthYear: "",
  });

  const [originalUserInfo, setOriginalUserInfo] = useState({});
  const [isEditing, setIsEditing] = useState(false);
  const [isPasswordModalOpen, setIsPasswordModalOpen] = useState(false); // State quản lý Popup
  const [isLoading, setIsLoading] = useState(false);

  const [password, setPassword] = useState({
    current: "",
    new: "",
    confirm: "",
  });

  // 1. Tải thông tin người dùng
  const fetchUserInfo = async () => {
    setIsLoading(true);
    try {
      const res = await axiosClient.get("/user/me");
      setUserInfo(res.data);
      setOriginalUserInfo(res.data);
    } catch (error) {
      console.error("Lỗi tải thông tin:", error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchUserInfo();
  }, []);

  // 2. Lưu thông tin cá nhân
  const handleSaveInfo = async () => {
    setIsLoading(true);
    try {
      await axiosClient.put("/user/me", userInfo);
      setOriginalUserInfo(userInfo);
      setIsEditing(false);
      alert("Cập nhật thông tin thành công!");
    } catch (error) {
      alert(error.response?.data?.message || "Cập nhật thất bại.");
    } finally {
      setIsLoading(false);
    }
  };

  // 3. Xử lý đổi mật khẩu
  const handleChangePassword = async () => {
    if (password.new !== password.confirm) {
      alert("Xác nhận mật khẩu không khớp.");
      return;
    }
    if (password.new.length < 6) {
      alert("Mật khẩu mới phải từ 6 ký tự trở lên.");
      return;
    }

    setIsLoading(true);
    try {
      // Giả sử API của bạn là /user/change-password hoặc tương tự
      await axiosClient.put("/user/change-password", {
        currentPassword: password.current,
        newPassword: password.new,
      });
      alert("Đổi mật khẩu thành công!");
      setIsPasswordModalOpen(false); // Đóng popup
      setPassword({ current: "", new: "", confirm: "" }); // Reset form
    } catch (error) {
      alert(error.response?.data?.message || "Mật khẩu hiện tại không đúng.");
    } finally {
      setIsLoading(false);
    }
  };

  const inputStyle = (editable) => ({
    padding: "10px",
    border: "1px solid #ddd",
    borderRadius: "4px",
    width: "100%",
    backgroundColor: editable ? "#fff" : "#f9f9f9",
    outline: "none",
  });

  // Giao diện Modal (Popup)
  const PasswordModal = () => {
    if (!isPasswordModalOpen) return null;
    return (
      <div
        style={{
          position: "fixed",
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          backgroundColor: "rgba(0,0,0,0.6)",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          zIndex: 2000,
        }}
      >
        <div
          style={{
            backgroundColor: "white",
            padding: "30px",
            borderRadius: "10px",
            width: "400px",
            boxShadow: "0 5px 15px rgba(0,0,0,0.3)",
            position: "relative",
          }}
        >
          <button
            onClick={() => setIsPasswordModalOpen(false)}
            style={{
              position: "absolute",
              top: "15px",
              right: "15px",
              border: "none",
              background: "none",
              cursor: "pointer",
              fontSize: "1.2em",
            }}
          >
            <FaTimes color="#999" />
          </button>

          <h3 style={{ marginTop: 0, color: "#c90000", marginBottom: "20px" }}>
            Đổi mật khẩu
          </h3>

          <div style={{ marginBottom: "15px" }}>
            <label
              style={{
                display: "block",
                marginBottom: "5px",
                fontSize: "0.9em",
              }}
            >
              Mật khẩu hiện tại
            </label>
            <input
              type="password"
              style={inputStyle(true)}
              value={password.current}
              onChange={(e) =>
                setPassword({ ...password, current: e.target.value })
              }
            />
          </div>

          <div style={{ marginBottom: "15px" }}>
            <label
              style={{
                display: "block",
                marginBottom: "5px",
                fontSize: "0.9em",
              }}
            >
              Mật khẩu mới
            </label>
            <input
              type="password"
              style={inputStyle(true)}
              value={password.new}
              onChange={(e) =>
                setPassword({ ...password, new: e.target.value })
              }
            />
          </div>

          <div style={{ marginBottom: "20px" }}>
            <label
              style={{
                display: "block",
                marginBottom: "5px",
                fontSize: "0.9em",
              }}
            >
              Xác nhận mật khẩu mới
            </label>
            <input
              type="password"
              style={inputStyle(true)}
              value={password.confirm}
              onChange={(e) =>
                setPassword({ ...password, confirm: e.target.value })
              }
            />
          </div>

          <div
            style={{
              textAlign: "right",
              display: "flex",
              gap: "10px",
              justifyContent: "flex-end",
            }}
          >
            <button
              onClick={() => setIsPasswordModalOpen(false)}
              style={{
                padding: "10px 20px",
                borderRadius: "5px",
                border: "1px solid #ddd",
                background: "white",
                cursor: "pointer",
              }}
            >
              Hủy
            </button>
            <button
              onClick={handleChangePassword}
              disabled={isLoading}
              style={{
                padding: "10px 20px",
                borderRadius: "5px",
                border: "none",
                background: "#c90000",
                color: "white",
                cursor: "pointer",
              }}
            >
              {isLoading ? "Đang xử lý..." : "Xác nhận đổi"}
            </button>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: "30px" }}>
      {/* THÔNG TIN CÁ NHÂN */}
      <div
        style={{
          border: "1px solid #eee",
          padding: "25px",
          borderRadius: "10px",
          backgroundColor: "#fff",
        }}
      >
        <h4
          style={{
            display: "flex",
            alignItems: "center",
            gap: "10px",
            color: "#c90000",
            marginBottom: "25px",
          }}
        >
          <FaUserEdit /> Thông tin tài khoản
        </h4>

        <div
          style={{
            display: "grid",
            gridTemplateColumns: "1fr 1fr",
            gap: "25px",
          }}
        >
          <div>
            <label
              style={{
                display: "flex",
                gap: "5px",
                fontWeight: "bold",
                marginBottom: "8px",
              }}
            >
              <FaUser /> Họ và Tên
            </label>
            <input
              style={inputStyle(isEditing)}
              value={userInfo.fullName || ""}
              disabled={!isEditing}
              onChange={(e) =>
                setUserInfo({ ...userInfo, fullName: e.target.value })
              }
            />
          </div>

          <div>
            <label
              style={{
                display: "flex",
                gap: "5px",
                fontWeight: "bold",
                marginBottom: "8px",
              }}
            >
              <FaEnvelope /> Email
            </label>
            <input
              style={inputStyle(false)}
              value={userInfo.email || ""}
              disabled
            />
          </div>

          <div>
            <label
              style={{
                display: "flex",
                gap: "5px",
                fontWeight: "bold",
                marginBottom: "8px",
              }}
            >
              <FaTransgender /> Giới tính
            </label>
            <select
              style={inputStyle(isEditing)}
              value={userInfo.gender || ""}
              disabled={!isEditing}
              onChange={(e) =>
                setUserInfo({ ...userInfo, gender: e.target.value })
              }
            >
              <option value="">Chọn giới tính</option>
              <option value="Nam">Nam</option>
              <option value="Nữ">Nữ</option>
              <option value="Khác">Khác</option>
            </select>
          </div>

          <div>
            <label
              style={{
                display: "flex",
                gap: "5px",
                fontWeight: "bold",
                marginBottom: "8px",
              }}
            >
              <FaBirthdayCake /> Ngày sinh
            </label>
            <div style={{ display: "flex", gap: "10px" }}>
              <input
                placeholder="Ngày"
                style={inputStyle(isEditing)}
                value={userInfo.birthDay || ""}
                disabled={!isEditing}
                onChange={(e) =>
                  setUserInfo({ ...userInfo, birthDay: e.target.value })
                }
              />
              <input
                placeholder="Tháng"
                style={inputStyle(isEditing)}
                value={userInfo.birthMonth || ""}
                disabled={!isEditing}
                onChange={(e) =>
                  setUserInfo({ ...userInfo, birthMonth: e.target.value })
                }
              />
              <input
                placeholder="Năm"
                style={inputStyle(isEditing)}
                value={userInfo.birthYear || ""}
                disabled={!isEditing}
                onChange={(e) =>
                  setUserInfo({ ...userInfo, birthYear: e.target.value })
                }
              />
            </div>
          </div>
        </div>

        <div
          style={{
            marginTop: "30px",
            textAlign: "right",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            borderTop: "1px solid #eee",
            paddingTop: "20px",
          }}
        >
          {/* NÚT BẤM HIỆN POPUP ĐỔI MẬT KHẨU NẰM Ở ĐÂY */}
          <button
            onClick={() => setIsPasswordModalOpen(true)}
            style={{
              background: "none",
              border: "none",
              color: "#007bff",
              cursor: "pointer",
              textDecoration: "underline",
              display: "flex",
              alignItems: "center",
              gap: "5px",
            }}
          >
            <FaLock /> Đổi mật khẩu đăng nhập?
          </button>

          {!isEditing ? (
            <button
              onClick={() => setIsEditing(true)}
              style={{
                padding: "10px 25px",
                backgroundColor: "#c90000",
                color: "white",
                border: "none",
                borderRadius: "5px",
                cursor: "pointer",
              }}
            >
              Chỉnh sửa thông tin
            </button>
          ) : (
            <div style={{ display: "flex", gap: "10px" }}>
              <button
                onClick={() => {
                  setIsEditing(false);
                  setUserInfo(originalUserInfo);
                }}
                style={{
                  padding: "10px 20px",
                  backgroundColor: "#6c757d",
                  color: "white",
                  border: "none",
                  borderRadius: "5px",
                  cursor: "pointer",
                }}
              >
                Hủy
              </button>
              <button
                onClick={handleSaveInfo}
                style={{
                  padding: "10px 20px",
                  backgroundColor: "#28a745",
                  color: "white",
                  border: "none",
                  borderRadius: "5px",
                  cursor: "pointer",
                }}
              >
                Lưu lại
              </button>
            </div>
          )}
        </div>
      </div>
      <PasswordModal /> {/* Gọi component Modal */}
    </div>
  );
};

export default PersonalInfo;
